    createBooking: {
        parameters: {
            query?: never;
            header?: {
                /**
                 * @description Optional key that makes retrying the request safe (T29, decided
                 *     2026-11-25). Send a new random value (e.g. a UUID) for each booking
                 *     attempt, and the same value when retrying it.
                 *     - Keys belong to the caller: the same key from two users is two keys.
                 *     - Only a created booking is remembered. A request that fails (any 4xx,
                 *       including 409 `ConfirmationRequired`) records nothing, so it can be
                 *       retried with the same key, e.g. with `confirm` added.
                 *     - A key is remembered for 24 hours from the booking's creation; after
                 *       that it counts as new.
                 *     - A repeat with the same body returns 201 with the same `Location` and
                 *       the booking as it is now (e.g. Cancelled if it was cancelled since),
                 *       and changes nothing: no second booking, history entry or event. It is
                 *       answered after authentication and request validation but before every
                 *       other check, so a repeat still succeeds after the slot has filled or
                 *       the rules or the caller's role have changed.
                 *     - A repeat with a different body is 422 `IdempotencyKeyReused`. Bodies
                 *       match when `serviceId`, `staffId`, `startUtc` (as an instant),
                 *       `customerEmail` (trimmed, ignoring case; absent is its own value) and
                 *       `overrideMinimumNotice` match; `confirm` is ignored.
                 *     - A repeat sent while the first request is still running waits for it,
                 *       then is answered as above. A different request sent at the same
                 *       time under the same key is refused, but it may be refused by an
                 *       earlier check (e.g. 403, 404 or 422 `CustomerNotFound`) rather than
                 *       `IdempotencyKeyReused`; either way nothing is booked.
                 *     - An invalid key (empty, sent twice, or not 1-64 characters from
                 *       `A-Z a-z 0-9 . _ -`) is 400 `ValidationFailed` on the field
                 *       `Idempotency-Key`. Keys are case-sensitive.
                 */
                "Idempotency-Key"?: components["parameters"]["IdempotencyKey"];
            };
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    serviceId: components["schemas"]["Id"];
                    staffId: components["schemas"]["Id"];
                    startUtc: components["schemas"]["UtcTimestamp"];
                    customerEmail?: components["schemas"]["Email"];
                    /** @default false */
                    overrideMinimumNotice?: boolean;
                    confirm?: components["schemas"]["Confirm"];
                };
            };
        };
        responses: {
            /** @description Booking created (Confirmed), or a repeat of an earlier request with the same `Idempotency-Key` (the booking as it is now). */
            201: {
                headers: {
                    Location?: string;
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Booking"];
                };
            };
            400: components["responses"]["ValidationFailed"];
            401: components["responses"]["Unauthenticated"];
            403: components["responses"]["Forbidden"];
            404: components["responses"]["NotFound"];
            409: components["responses"]["SlotConflictOrConfirmation"];
            /** @description `MinimumNotice` (R3), `SlotUnavailable` (R8), `StaffNotAssignedToService`, `CustomerNotFound`, or `IdempotencyKeyReused` (the key was used for a different request). */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "code": "MinimumNotice",
                     *       "message": "This slot is too soon to book.",
                     *       "rule": "R3",
                     *       "details": {
                     *         "minNoticeMinutes": 120
                     *       }
                     *     }
                     */
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
